def count_rotation(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Find the first index where arr[i] < arr[i-1]; that index == rotation count
    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            return i
    return 0

assert count_rotation([3, 2, 1]) == 1
